    n=d.styles['Normal']; n.font.name='Microsoft YaHei'; n._element.rPr.rFonts.set(qn('w:eastAsia'),'Microsoft YaHei'); n.font.size=Pt(10.2); n.paragraph_format.space_after=Pt(4); n.paragraph_format.line_spacing=1.2
